            "mentor_analogy": "就像你在追最愛的影集或打遊戲，整個人靈魂像被吸進螢幕裡一樣，旁邊有人叫你名字你完全聽不到！這種『全神貫注、深陷其中』在英文裡就是 be engaged in / be absorbed in！",
