              "C": "【避坑】engaging 是主動形容詞，意思是『迷人的、引人入勝的』，拿來形容人表示『這男子很迷人』，大鬧語意笑話！",
              "D": "【避坑】engagement 是名詞（訂婚、約會），放在 was so 後面文法直接崩塌！"
